```

- 安装其他依赖

```
pnpm add rimraf -D
```

3. 配置rollup.config.js

```js
import typescript from 'rollup-plugin-typescript2'; // 处理typescript
import babel from '@rollup/plugin-babel';

export default [
    {
        input: 'src/index.ts',
        plugins: [
            typescript(), // typescript 转义
            babel({
                babelrc: false,
                presets: [['@babel/preset-env', { modules: false, loose: true }]],
                plugins: [['@babel/plugin-proposal-class-properties', { loose: true }]],
                exclude: 'node_modules/**',
            })
        ],
        output: [
            { file: 'dist/index.js', format: 'cjs' },
            { file: 'dist/index.esm.js', format: 'es' }
        ]
    }
];
```
4. 配置tsconfig.json

```json
{
  "include": ["./src/*"],
  "compilerOptions": {
    "target": "ES2019",
    "module": "ESNext",
    "moduleResolution": "node",
    "strict": true,
    "esModuleInterop": true,
    "noImplicitOverride": true,
    "noUnusedLocals": true,
    "resolveJsonModule": true,
    "useUnknownInCatchVariables": false,
    "typeRoots": ["./types", "./node_modules/@types"]
  },
  "types": ["jest"]
}

```

5. 配置package.json

添加dev和build命令脚本，如下所示：
```json
{
  ...
  "main": "dist/index.js",
  "type": "module", // rollup新增的配置项
  "scripts": {
    "dev": "rimraf dist && rollup -c rollup.config.ts -w",
    "build": "rimraf dist && rollup -c rollup.config.ts"
  },
  ...
}
```

6. 编写demo代码

```
// sum.ts
export default function sum(a: number, b:number){
  return a+b;
}

// index.ts
import sum from './sum';

console.log(sum(1, 2));

export default {
    sum
}
```
7. 测试运行

```
pnpm run dev

pnpm run build
```

查看生成`dist/index.js` 和 `dist/index.esm.js`。

